//! Файл: settings/catalog/dex_fail.rs
//! Что делает: настройки задачи t153 (16.11.2026), решение 339 — ошибка чтения одного пула касается только этого пула
//! (venues/bsc_dex/pools/pool_fail.rs): сессия пачки подписки не рвётся, пул недостоверен и перечитывается по
//! расписанию с растущей паузой. Раздел «DEX», область «площадка», только площадка DEX — .dex_venue(). Обе
//! необязательные, значений нет: не задана dex.pool_fail_pause_ms — как раньше (ошибка рвёт сессию пачки).
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «DEX»).

use super::{V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решения 339. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static DEX_FAIL: &[SettingDef] = &[
    d("DEX", "dex.pool_fail_pause_ms", K::Integer, L::Positive, "мс", V, "Решение 339: ошибка чтения ОДНОГО пула (откат контракта, например DODO «KJUDGE_ERROR», ответ не по ABI, сбой узла на этом пуле, ошибка eth_blockNumber при реорге) касается только этого пула — для всех видов пулов и всех путей (перечитывание по событию, пары многомонетного пула, пары общего контракта WooFi, пулы «каждым блоком», Balancer V2, LB V2.1, очередь повтора): пул недостоверен (в котировки и сделки не идёт), причина — на экране «Монеты» и в журнале (одна запись на начало неудач и на смену причины), остальные пулы пачки работают без переподключения подписки и без перечитывания. Повтор — не раньше этой паузы; с каждой неудачей подряд пауза удваивается до dex.pool_fail_pause_max_ms; пул на паузе по своим событиям не читается (позиция события отмечается, повтор прочитает не раньше неё). Предел попыток очереди повтора — dex.pool_load_retries (дальше пул брошен и читается снова только по своему событию — тоже не раньше паузы). Обрыв WebSocket, пропуск логов лентой, лог без позиции, смена источника событий — по-прежнему переподключение. Не задана — как раньше: прочая ошибка (кроме StaleData) рвёт сессию пачки и перечитывает все её пулы. Необязательна").dex_venue().optional(),
    d("DEX", "dex.pool_fail_pause_max_ms", K::Integer, L::Positive, "мс", V, "Решение 339: потолок растущей паузы повтора пула после неудач чтения (dex.pool_fail_pause_ms удваивается с каждой неудачей подряд, но не больше этого). Действует только при заданной dex.pool_fail_pause_ms. Не задана — пауза не растёт (всегда dex.pool_fail_pause_ms). Необязательна").dex_venue().optional(),
];
